&lt;p&gt;&lt;span style="font-size:12px"&gt;&lt;strong&gt;What:&lt;/strong&gt;&lt;span style="font-family:calibri,sans-serif"&gt; &lt;/span&gt;&lt;span style="font-family:calibri,sans-serif"&gt; &lt;/span&gt;&lt;span style="font-family:roboto,roboto_embeddedfont,roboto_msfontservice,sans-serif"&gt;Conversation&amp;nbsp;with&lt;/span&gt;&lt;strong&gt;&amp;nbsp;Morgan&amp;nbsp;Rubanow, BLM Community Outreach Specialist&lt;/strong&gt;&lt;span style="font-family:roboto,roboto_embeddedfont,roboto_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;span style="font-family:roboto,roboto_embeddedfont,roboto_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
